#include <iostream>
#include <sstream>
#include <iomanip>

struct AccountRecord {
    int accountNumber{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

void printFormatted(std::ostream& out, const AccountRecord& rec) {
    out << std::left << std::setw(10) << rec.accountNumber
        << std::setw(16) << rec.lastName
        << std::setw(11) << rec.firstName
        << std::right << std::setw(10) << std::fixed << std::setprecision(2) << rec.balance
        << "\n";
}

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);
    AccountRecord blank{};
    for (int i = 0; i < 3; ++i) {
        stream.write(reinterpret_cast<const char*>(&blank), sizeof(AccountRecord));
    }

    AccountRecord user2{2, "Barker", "Doug", 87.99};
    stream.seekp((2 - 1) * sizeof(AccountRecord));
    stream.write(reinterpret_cast<const char*>(&user2), sizeof(AccountRecord));

    std::cout << "--- Formatted Report ---\n";
    std::cout << std::left << std::setw(10) << "Account" << std::setw(16) << "Last Name"
              << std::setw(11) << "First Name" << std::right << std::setw(10) << "Balance" << "\n";
    stream.seekg(0);
    AccountRecord temp{};
    while (stream.read(reinterpret_cast<char*>(&temp), sizeof(AccountRecord))) {
        if (temp.accountNumber != 0) {
            printFormatted(std::cout, temp);
        }
    }
    return 0;
}

#include <iostream>
#include <sstream>
#include <iomanip>

struct AccountRecord {
    int accountNumber{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

void writeRecord(std::iostream& io, int slot, const AccountRecord& rec) {
    io.seekp((slot - 1) * sizeof(AccountRecord));
    io.write(reinterpret_cast<const char*>(&rec), sizeof(AccountRecord));
}

AccountRecord readRecord(std::iostream& io, int slot) {
    AccountRecord rec{};
    io.seekg((slot - 1) * sizeof(AccountRecord));
    io.read(reinterpret_cast<char*>(&rec), sizeof(AccountRecord));
    return rec;
}

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    AccountRecord blank{};
    for (int i = 0; i < 5; ++i) {
        stream.write(reinterpret_cast<const char*>(&blank), sizeof(AccountRecord));
    }

    AccountRecord newAcc{3, "Dunn", "Stacey", 314.33};
    AccountRecord checkSlot = readRecord(stream, 3);
    if (checkSlot.accountNumber == 0) {
        writeRecord(stream, 3, newAcc);
        std::cout << "Account #" << newAcc.accountNumber << " created successfully.\n";
    }

    AccountRecord current = readRecord(stream, 3);
    if (current.accountNumber != 0) {
        current.balance += 50.00;
        writeRecord(stream, 3, current);
        std::cout << "Account #3 updated. New balance: " << std::fixed << std::setprecision(2) << current.balance << "\n";
    }

    writeRecord(stream, 3, blank);
    std::cout << "Account #3 deleted.\n";

    AccountRecord postDelete = readRecord(stream, 3);
    std::cout << "Slot 3 account number after deletion: " << postDelete.accountNumber << "\n";

    return 0;
}
